const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: 'y' },
      { kind: 'text', payload: 'O' },
      { kind: 'text', payload: 'P(-3,2)' },
      { kind: 'text', payload: '第二象限' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var ox = Math.round(W * 0.42);
    var oy = Math.round(H * 0.62);
    var unit = Math.max(10, Math.min(W / 10, H / 9));
    var px = ox - 3 * unit;
    var py = oy - 2 * unit;
    var paths = [];
    var children = [];

    function addPath(id, cmds, extra) {
      paths.push({ id: id, commands: cmds });
      var node = { type: 'path', pathId: id };
      if (extra) {
        for (var k in extra) { node[k] = extra[k]; }
      }
      children.push(node);
    }

    function seg(id, x1, y1, x2, y2, extra) {
      addPath(id, visualSdk.polyline([[x1, y1], [x2, y2]]), extra);
    }

    function dashLine(prefix, x1, y1, x2, y2) {
      var dx = x2 - x1;
      var dy = y2 - y1;
      var len = Math.sqrt(dx * dx + dy * dy);
      if (len < 0.001) { return; }
      var ux = dx / len;
      var uy = dy / len;
      var d = 6;
      var g = 4;
      var t = 0;
      var i = 0;
      var t2;
      while (t < len - 0.001) {
        t2 = Math.min(t + d, len);
        seg(prefix + '_' + i, x1 + ux * t, y1 + uy * t, x1 + ux * t2, y1 + uy * t2,
            { stroke: '#5b6b80', strokeWidth: 1.5 });
        i = i + 1;
        t = t2 + g;
      }
    }

    function label(text, x, y, anchor, fill) {
      children.push({ type: 'label', text: text, x: x, y: y, fontSize: 14,
                      textAnchor: anchor || 'start', fill: fill || '#22303f' });
    }

    // 坐标轴（含箭头）
    addPath('axisX', visualSdk.arrow(20, oy, W - 16, oy, {}),
            { stroke: '#26354a', strokeWidth: 1.6 });
    addPath('axisY', visualSdk.arrow(ox, H - 16, ox, 18, {}),
            { stroke: '#26354a', strokeWidth: 1.6 });

    // 刻度：x 轴上 -3、2；y 轴上 2、-3
    seg('tickX1', px, oy - 4, px, oy + 4, { stroke: '#26354a', strokeWidth: 1.4 });
    seg('tickX2', ox + 2 * unit, oy - 4, ox + 2 * unit, oy + 4,
        { stroke: '#26354a', strokeWidth: 1.4 });
    seg('tickY1', ox - 4, py, ox + 4, py, { stroke: '#26354a', strokeWidth: 1.4 });
    seg('tickY2', ox - 4, oy + 3 * unit, ox + 4, oy + 3 * unit,
        { stroke: '#26354a', strokeWidth: 1.4 });

    // 点 P 到两坐标轴的虚线垂线
    dashLine('dashH', px, py, ox, py);
    dashLine('dashV', px, py, px, oy);

    // 点 P 与垂足
    addPath('pointP', visualSdk.circle(px, py, 4),
            { fill: '#c0392b', stroke: '#c0392b' });
    addPath('footH', visualSdk.circle(ox, py, 2.4),
            { fill: '#5b6b80', stroke: '#5b6b80' });
    addPath('footV', visualSdk.circle(px, oy, 2.4),
            { fill: '#5b6b80', stroke: '#5b6b80' });

    // 文字标注（全部为原题已有内容）
    label('x', W - 14, oy - 8, 'end');
    label('y', ox + 8, 24, 'start');
    label('O', ox - 14, oy + 16, 'end');
    label('P(-3,2)', px - 10, py - 10, 'end', '#c0392b');
    label('第二象限', Math.max(24, ox - 4.4 * unit),
          Math.max(40, oy - 3.6 * unit), 'start', '#1f6f4a');

    return {
      schemaVersion: 1,
      sceneId: 'quadrant-pointP',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
